class Solution {
public:
    vector<int> canSeePersonsCount(vector<int>& heights) {
        int n = heights.size();
        vector<int> answer(n, 0);
        vector<int> stk;
        stk.reserve(n);
        for (int i = n - 1; i >= 0; i--) {
            int count = 0;
            while (!stk.empty() && heights[stk.back()] < heights[i]) {
                stk.pop_back();
                count++;
            }
            if (!stk.empty()) {
                count++;
            }
            answer[i] = count;
            stk.push_back(i);
        }
        return answer;
    }
};
